/* Kişisel Hekimim 3.0 — LOCAL UI PROTOTYPE. No real clinical analysis. */
let caseWizardStep=0,caseWizardMode='new',caseWizardDraft={},caseWizardPreview='assessment',caseWizardLayers=['nerve','bone'];
let assistantTab='chat',assistantSources=true,assistantHistoryCutoffs={};
let simTab='model',simView='iso',simRotation=0,simZoom=100,simOpacity=85,simLayers=['bone','teeth','nerve','implant'];
let imageTab='findings',imageModality='CBCT',imageOrientation='axial',imageZoom=100,imageOpacity=80,imageExpanded='nerve',imageReviewed=[],imageMeasure='distance',imageNotes='',imageView='diagram';
const pages=[['home','⌂','Ana Sayfa'],['case','▣','Yeni Vaka / Dosya'],['assistant','✧','AI Klinik Asistanım'],['imaging','◈','Görüntü Analizi'],['simulation','⬡','3D Simülasyon'],['consult','♧','Konsültasyon'],['network','♧','Hekim Ağı'],['patients','▤','Hastalarım'],['calendar','▦','Randevularım'],['notifications','♧','Bildirim Merkezi'],['profile','♙','Profilim'],['reports','▤','Uzman Raporları'],['settings','⚙','Ayarlar']];
let peerState={consults:[],self_id:null};async function loadPeers(){try{let r=await fetch('/api/peer-consults');if(r.ok){peerState=await r.json();if(page==='consult'||page==='network'||page==='notifications')render()}}catch(e){console.warn(e)}}
let storedFiles=[];async function loadFiles(){try{let r=await fetch('/api/attachments');if(r.ok){storedFiles=(await r.json()).files||[];if(page==='imaging'||page==='case'||page==='patients')render()}}catch(e){console.warn(e)}}
let networkState={doctors:[],connections:[],self_id:null}; let state={cases:[],notes:[],requests:[],appointments:[],contacts:[],messages:[],clinical_reports:[],case_plans:[],case_details:[],profile:null},page='home',caseId='',imagingLayers=['nerve','bone','tooth'],simMode='before',simScenario='A',chosenReport='',theme=localStorage.getItem('kh-theme')||'teal', font=localStorage.getItem('kh-font')||'normal';
const palettes={teal:'#087D80',blue:'#245FAC',purple:'#6954A8',dark:'#253746'};
const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const el=id=>document.getElementById(id);
const current=()=>state.cases.find(c=>c.id===caseId)||state.cases[0];
const card=(html,more='')=>`<section class="card ${more}">${html}</section>`;
const field=(label,name,value='',type='text')=>`<div class="field"><label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}">${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}">`}</div>`;
const btn=(text,target,kind='outline')=>`<button class="btn ${kind}" data-page="${target}">${text}</button>`;
const selectCase=()=>`<div class="field"><label>Aktif vaka — bütün modüllerde korunur</label><select id="activeCase">${state.cases.map(c=>`<option value="${esc(c.id)}" ${caseId===c.id?'selected':''}>${esc(c.id)} · ${esc(c.subject)}</option>`).join('')}</select></div>`;
const homeIconPaths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',case:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2l-2 10H5z"/>',assistant:'<path d="m12 2 2.3 7.7L22 12l-7.7 2.3L12 22l-2.3-7.7L2 12l7.7-2.3z"/>',imaging:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="2"/><path d="m3 17 6-5 4 3 3-3 5 5"/>',simulation:'<path d="m12 2 9 5v10l-9 5-9-5V7zM3 7l9 5 9-5M12 12v10"/>',consult:'<path d="M4 4h16a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-6 4V6a2 2 0 0 1 1-2z"/><path d="M7 10h10M7 14h7"/>',network:'<circle cx="9" cy="8" r="3"/><circle cx="18" cy="9" r="2"/><path d="M2 21v-3c0-4 14-4 14 0v3M17 16c3 0 5 2 5 5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18"/>',notifications:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>'};
function khIcon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${homeIconPaths[name]||homeIconPaths.home}</svg>`}
function nav(){const b=el('notificationCount');if(b){let pending=(state.patient_requests||[]).filter(x=>x.status==='bekliyor').length+(peerState.consults||[]).filter(x=>x.recipient_id===peerState.self_id&&x.status==='pending').length;b.textContent=pending;b.hidden=!pending}const items=[['home','Ana Sayfa'],['case','Vaka'],['assistant','AI Asistan'],['imaging','Görüntü'],['simulation','Simülasyon'],['consult','Konsültasyon'],['network','Hekim Ağı'],['calendar','Randevular'],['notifications','Bildirimler']];el('nav').innerHTML=items.map(([id,label])=>`<button class="kh-v7-nav-item ${page===id?'active':''}" data-page="${id}" type="button">${khIcon(id)}<span>${label}</span></button>`).join('');el('pageTitle').textContent=pages.find(p=>p[0]===page)?.[2]||'Ana Sayfa';}

async function refresh(){let r=await fetch('/api/state');if(!r.ok)throw Error('Sunucuya erişilemiyor');state=await r.json();if(!state.cases.some(c=>c.id===caseId))caseId=state.cases[0]?.id||'';render()}
async function post(path,data){try{const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let out=await r.json();if(!r.ok)throw Error(out.error||'İşlem başarısız');if(path==='user/password'){location.href='/';return true}await refresh();return true}catch(err){alert('Hata: '+err.message);return false}}
function go(p){if(p==='network')stage5Tab='network';if(p==='consult')stage5Tab='requests';if(p==='case'&&page!=='case'&&caseWizardStep===0&&caseWizardMode==='new')caseWizardDraft=wizardDraftFromCase(null);page=p;el('content').scrollIntoView({block:'start'});render()}
function quickCard(id,icon,title,desc){return `<button type="button" class="card feature-card" data-page="${id}"><span class="feature-icon" aria-hidden="true">${icon}</span><span class="feature-copy"><strong>${title}</strong><small>${desc}</small></span><span class="feature-arrow" aria-hidden="true">↗</span></button>`}
function home(){const c=current();const tools=[['imaging','Görüntü Analizi','Radyoloji, patoloji ve diğer tıbbi görüntülerde analiz çalışma alanı.'],['simulation','3D Simülasyon','Klinik senaryoları ve girişimsel işlemler için etkileşimli planlama.'],['consult','Konsültasyon','Uzman görüşü al, vaka tartış, multidisipliner değerlendirme yap.'],['network','Hekim Ağı','Hekimlerle bağlantı kur, vaka paylaş ve iş birliği yap.'],['calendar','Randevular','Hasta randevularını görüntüle, planla ve yönet.'],['notifications','Bildirimler','Vaka güncellemeleri, konsültasyon yanıtları ve duyurular.']];return `<div class="kh-v7-home">
<section class="kh-v7-hero"><div class="kh-v7-hero-copy"><div class="kh-v7-hero-heading">${khIcon('assistant')}<h2>AI Klinik Asistanım</h2></div><p>Yeni vaka analizi, klinik soru ve bilimsel değerlendirme</p><button type="button" class="kh-v7-main-cta" data-page="case">Yeni Vaka Analizi <span>→</span></button><button type="button" class="kh-v7-chat-link" data-page="assistant">AI Asistan ile sohbet et ↗</button></div></section>
<div class="kh-v7-card-grid">${tools.map(([id,title,desc])=>`<button class="kh-v7-feature ${id==='consult'||id==='network'?'accent':''}" type="button" data-page="${id}"><span class="kh-v7-feature-icon">${khIcon(id)}</span><span class="kh-v7-feature-copy"><strong>${title}</strong><small>${desc}</small></span><span class="kh-v7-arr">→</span></button>`).join('')}</div>
<section class="kh-v7-active"><div class="kh-v7-active-heading"><div><h2>⌁ &nbsp;Aktif Vaka</h2><p>Üzerinde çalıştığın güncel vaka</p></div><button data-page="case" type="button">Tüm Vakalar →</button></div><div class="kh-v7-active-record"><div class="kh-v7-record-symbol">${khIcon('case')}</div><div class="kh-v7-record-body">${c?`<strong>${esc(c.subject)}</strong><div class="kh-v7-tags"><span>${esc(c.patient||'Örnek hasta')}</span><span>${esc(c.specialty||'Branş belirtilmedi')}</span><span>${esc(c.id)}</span></div><p>Seçili yerel vaka kaydı · Gerçek hasta verisi kullanmayın.</p>`:'<strong>Henüz aktif vaka bulunmuyor.</strong><p>Yeni bir örnek vaka oluşturarak çalışmaya başlayın.</p>'}</div><button class="kh-v7-record-open" data-page="case" type="button">${c?'Vaka Detayını Görüntüle':'Yeni Vaka Oluştur'} →</button></div></section>
</div>`}

function wizardDraftFromCase(c){const d=(state.case_details||[]).find(x=>x.case_id===c?.id)||{};return {patient:c?.patient||'',specialty:c?.specialty||'dental',subject:c?.subject||'',history:c?.history||'',medications:c?.medications||'',age:d.age||'',complaint:d.complaint||'',assessment_type:d.assessment_type||'surgery',question:d.question||''}}
function wizardOptions(options,selected){return options.map(([v,label])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`).join('')}
function wizardText(label,name,placeholder='',rows=0){const value=caseWizardDraft[name]||'';return `<div class="field"><label for="wizard-${name}">${label}</label>${rows?`<textarea id="wizard-${name}" data-wizard-field="${name}" rows="${rows}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="wizard-${name}" data-wizard-field="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${name==='age'?'type="number" min="0" max="125"':''}>`}</div>`}
function wizardSelect(label,name,opts){return `<div class="field"><label for="wizard-${name}">${label}</label><select id="wizard-${name}" data-wizard-field="${name}">${wizardOptions(opts,caseWizardDraft[name])}</select></div>`}
function casePage(){const names=['Vaka Bilgileri','Görüntüleme','AI Analiz Önizleme','Simülasyon'];let inner='';
if(caseWizardStep===0){inner=`<h2>Hasta ve Vaka Bilgileri</h2><p class="muted">Kurgusal vaka bilgilerini girin; gerçek hasta verisi kullanmayın.</p><div class="wizard-fields">${wizardText('Hasta kodu / takma adı','patient','Örnek Hasta 004')}${wizardSelect('Uzmanlık alanı','specialty',[['dental','Diş Hekimliği'],['maxillo','Ağız, Diş ve Çene Cerrahisi'],['ortho','Ortodonti'],['cardio','Kardiyoloji'],['internal','İç Hastalıkları'],['orthopedic','Ortopedi ve Travmatoloji'],['other','Diğer branşlar']])}${wizardSelect('Değerlendirme türü','assessment_type',[['surgery','Cerrahi planlama'],['treatment','Tedavi seçeneklerini karşılaştırma'],['prosthesis','Protez / implant planlama'],['growth','Ortodontik gelişim'],['diagnosis','Tanısal inceleme']])}${wizardText('Hastanın yaşı','age','Yaş')}${wizardText('Vaka konusu','subject','Örn. Alt gömülü üçüncü molar')}${wizardText('Şikâyet ve muayene bulguları','complaint','Şikâyet, klinik bulgular ve muayene notları...',3)}${wizardText('Kronik hastalıklar ve tıbbi geçmiş','history','Hastalıklar, geçirilmiş işlemler, alerjiler...',2)}${wizardText('Kullanılan ilaçlar','medications','İlaçlar ve dozları',2)}${wizardText('Yapay zekâya klinik sorunuz','question','Bu vaka için hangi riskler ve tedavi seçenekleri değerlendirilmelidir?',3)}</div>`}
else if(caseWizardStep===1){const files=storedFiles.filter(f=>f.case_id===caseId);inner=`<h2>Tetkik ve Görüntüleme</h2><p class="muted">Hastanın görüntülerini ve klinik belgelerini değerlendirmeye ekleyebileceğiniz bölüm.</p><div class="wizard-docgrid">${[['◈','CBCT / Tomografi'],['▣','Panoramik Röntgen'],['▤','MR / DICOM'],['✚','Kan Tahlili / PDF']].map(([ic,n])=>`<div class="wizard-doctype"><span>${ic}</span><strong>${n}</strong></div>`).join('')}</div><div class="wizard-upload"><div class="wizard-upload-icon">⇧</div><h3>Görüntü Yükleme Alanı</h3><p>PDF, PNG, JPEG ve DICOM dosyalarını (en fazla 6 MB) kurgusal vaka kaydına ekleyebilirsiniz.</p>${caseWizardMode==='edit'&&caseId?`<form data-form="upload"><input name="attachment" type="file" accept=".pdf,.png,.jpg,.jpeg,.dcm,application/dicom" required><button class="btn" type="submit">Dosyayı Bu Vakaya Ekle</button></form>`:'<p class="muted mini">Dosya eklemek için önce birinci adımda vakayı kaydedin.</p>'}</div>${caseWizardMode==='edit'&&caseId?`<div class="wizard-existing"><h3>Ekli Belgeler</h3>${files.map(f=>`<div class="item row"><span>${esc(f.filename)} · ${Math.ceil(f.size/1024)} KB</span><a class="btn outline small" href="/api/attachment/${f.id}" target="_blank" rel="noopener">Aç</a></div>`).join('')||'<p class="muted">Henüz dosya eklenmedi.</p>'}</div>`:''}<h3>Anatomik İşaretleme Katmanları</h3><div class="wizard-layers">${[['nerve','#238BE0','Mandibular kanal / sinir'],['bone','#22AD83','Kortikal kemik sınırları'],['tooth','#B28AE0','Diş ve kök segmentasyonu'],['risk','#E9903C','Kritik yakınlık bölgeleri']].map(([id,color,label])=>`<label class="wizard-layer"><span style="background:${color}" class="wizard-dot"></span><span>${label}</span><input type="checkbox" data-wizard-layer="${id}" ${caseWizardLayers.includes(id)?'checked':''}></label>`).join('')}</div>`}
else if(caseWizardStep===2){inner=`<h2>AI Klinik Değerlendirme</h2><p class="muted">Klinik raporun daha önce onaylanan yerleşimi.</p><div class="wizard-summary"><div class="wizard-summary-head"><span>✧</span><b>Vaka Özeti</b><span class="wizard-demo">Demo</span></div><p><strong>Klinik sorunuz:</strong> ${esc(caseWizardDraft.question||'Henüz klinik soru girilmedi.')}</p><p><strong>Şikâyet:</strong> ${esc(caseWizardDraft.complaint||'Belirtilmedi.')}</p></div><div class="wizard-resultcards">${[['Klinik Özet','Hastanın önemli bilgileri ve klinik bulguları'],['Ayırıcı Tanı ve Riskler','Değerlendirilecek olasılıklar ve dikkat edilmesi gereken durumlar'],['Tedavi Seçenekleri','Alternatif yaklaşımlar ve karşılaştırmalı planlama'],['Literatür ve Kılavuzlar','Bilimsel dayanaklar ve kaynak bağlantıları']].map(([t,d])=>`<section class="wizard-result"><strong>${t}</strong><p>${d}</p></section>`).join('')}</div><p class="wizard-warning">Gerçek bir klinik analiz veya tedavi önerisi oluşturulmadı.</p>`}
else{inner=`<h2>3D İşlem Simülasyonu</h2><div class="wizard-tabs">${[['assessment','Anatomi'],['procedure','İşlem Planı'],['outcome','Sonuç']].map(([v,l])=>`<button type="button" class="${caseWizardPreview===v?'active':''}" data-wizard-preview="${v}">${l}</button>`).join('')}</div><div class="wizard-sim"><div class="wizard-sim-icon">${caseWizardPreview==='assessment'?'◈':caseWizardPreview==='procedure'?'⇢':'◷'}</div><h3>${caseWizardPreview==='assessment'?'3D Anatomik Model':caseWizardPreview==='procedure'?'İşlem Planlama':'Olası Sonuçlar'}</h3><p>Hasta bazlı üç boyutlu modeller ve doğrulanmış simülasyon sonuçları ileride burada gösterilecek.</p><span class="wizard-demo">Simülasyon motoru henüz bağlı değil</span></div><section class="wizard-result"><strong>◇ Hekim Kontrolü</strong><p>Simülasyonların doğruluğu, ölçüm belirsizlikleri ve uzman doğrulaması gerçek sürümde ayrıca gösterilecek.</p></section>`}
return `<div class="wizard-shell"><header class="wizard-header"><div class="wizard-brand"><div class="wizard-brand-icon">✚</div><div><b>Kişisel Hekimim</b><small>AI KLİNİK ASİSTANI · 3.0</small></div><span class="wizard-online">● Çevrim içi</span></div><h1>Yeni Vaka Analizi</h1><p>Hasta verileriyle klinik değerlendirme ve simülasyon çalışma alanı.</p><div class="wizard-progress-top"><span>${names[caseWizardStep]}</span><span>${caseWizardStep+1}/4</span></div><div class="wizard-progress">${names.map((n,i)=>`<span class="${i<=caseWizardStep?'done':''}"></span>`).join('')}</div></header><div class="wizard-body"><div class="wizard-modebar"><div class="field"><label>Çalışma</label><select id="wizardCaseMode"><option value="new" ${caseWizardMode==='new'?'selected':''}>Yeni vaka oluştur</option><option value="edit" ${caseWizardMode==='edit'?'selected':''}>Kayıtlı vakayı aç / düzenle</option></select></div>${caseWizardMode==='edit'?`<div class="field"><label>Kayıtlı vaka</label><select id="wizardExistingCase">${state.cases.map(c=>`<option value="${esc(c.id)}" ${c.id===caseId?'selected':''}>${esc(c.patient)} · ${esc(c.subject)}</option>`).join('')}</select></div>`:''}</div>${inner}<div class="wizard-footer">${caseWizardStep>0?'<button type="button" class="btn outline" data-wizard-nav="back">← Geri</button>':''}<button type="button" class="btn" data-wizard-nav="${caseWizardStep===3?'restart':'next'}">${caseWizardStep===0?(caseWizardMode==='new'?'Vakayı Kaydet ve Devam Et →':'Değişiklikleri Kaydet ve Devam Et →'):caseWizardStep===3?'Yeni Vaka Başlat':'Devam Et →'}</button></div><p class="wizard-footnote">Onaylanmış tasarım · Yalnızca kurgusal veriler kullanın. Gerçek klinik değerlendirme yapılmaz.</p></div></div>`}
function assistant(){
 const all=state.messages.filter(m=>m.case_id===caseId).sort((a,b)=>a.id-b.id), cutoff=assistantHistoryCutoffs[caseId]||0;
 const list=all.filter(m=>Number(m.id)>cutoff);
 const files=storedFiles.filter(f=>f.case_id===caseId);
 let content='';
 if(assistantTab==='chat'){
  content=`<div class="kh-chat-container" id="chatbox">${list.length?list.map(m=>`<div class="kh-chat-row ${m.role==='user'?'user':''}">${m.role==='user'?'':'<span class="kh-chat-avatar">✧</span>'}<div class="kh-chat-bubble">${esc(m.body)}</div></div>`).join(''):'<div class="kh-chat-row"><span class="kh-chat-avatar">✧</span><div class="kh-chat-bubble">Merhaba Doktor! Klinik değerlendirme, bilimsel literatür, hasta verilerinin incelenmesi ve işlem planlamasında yardımcı olacak çalışma alanınıza hoş geldiniz. Genel soru sorabilir veya seçili vaka üzerinde çalışabilirsiniz.<br><br><small>Bu sürümde gerçek AI veya klinik analiz bağlı değildir.</small></div></div>'}</div>`;
  if(!list.length)content+=`<h3 style="margin:18px 0 10px">Ne hakkında destek almak istersiniz?</h3><div class="kh-quick-grid">${[['Ayırıcı Tanı','Bu vaka için hangi ayırıcı tanılar incelenmeli?'],['Tetkik Yorumlama','Tetkikleri değerlendirirken hangi bilgileri gözden geçirmeliyim?'],['Tedavi Seçenekleri','Bu vaka için tedavi seçenekleri nasıl karşılaştırılabilir?'],['İşlem Simülasyonu','Bu vaka için hangi işlem simülasyonları kullanılabilir?']].map(x=>`<button type="button" data-quick-prompt="${esc(x[1])}">${esc(x[0])} <span style="float:right">↗</span></button>`).join('')}</div>`;
  content+=`<form data-form="message" class="kh-chat-compose"><textarea name="body" required placeholder="Klinik sorunuzu veya vaka hakkındaki değerlendirme isteğinizi yazın..."></textarea><div class="btnrow"><button type="button" class="btn outline" data-assistant-tab="files">♧ &nbsp; Belge Ekle</button><button class="btn" type="submit">Gönder ↗</button></div></form>`;
 }else if(assistantTab==='files'){
  content=`<h3>Vaka Belgeleri ve Görüntüler</h3><p class="muted">Örnek vakaya PDF, röntgen, BT, CBCT ve laboratuvar sonuçları ekleyin. Gerçek tıbbi analiz yapılmaz.</p><div class="kh-files-grid">${[['♧','Kan Tahlili'],['◈','Röntgen / CBCT'],['▤','MR / Tomografi'],['▣','Tıbbi Rapor']].map(x=>`<div class="kh-file-tile"><span style="font-size:26px;color:#087d80">${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><form data-form="upload"><div class="field"><label>Deneme dosyası seçin (PDF / PNG / JPEG / DICOM, en fazla 6 MB)</label><input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.dcm" required></div><button class="btn" type="submit">Seçilen dosyayı vakaya kaydet</button></form><div class="list" style="margin-top:16px">${files.map(f=>`<div class="item row"><div><b>${esc(f.filename)}</b><p>${Math.ceil(f.size/1024)} KB</p></div><a class="btn outline small" href="/api/attachment/${Number(f.id)}" target="_blank" rel="noopener">Aç ↗</a></div>`).join('')||'<p class="muted">Bu vakada kayıtlı deneme dosyası yok.</p>'}</div><button type="button" class="btn outline" data-assistant-tab="chat">Sohbete Dön</button>`;
 }else{
  content=`<h3>Bilimsel Kaynak Tercihleri</h3><label class="kh-source-row"><input type="checkbox" id="assistantSourcesToggle" ${assistantSources?'checked':''}> Yanıtlarda doğrulanabilir kaynak ve yayın tarihlerini göster</label><div class="kh-source-row"><strong>Kaynak Doğrulama</strong><p class="muted">Gelecekte klinik kılavuzlar, sistematik derlemeler ve bilimsel araştırmaların bağlantıları burada listelenecek. Şu an canlı literatür taraması yapılmıyor.</p></div><button type="button" class="btn outline" data-assistant-tab="chat">Sohbete Dön</button>`;
 }
 return `<div class="kh-asst-head"><div class="kh-asst-icon">✧</div><div><h2>AI Klinik Asistanım</h2><p>Bilimsel destek · Klinik analiz · Simülasyon</p></div></div>${card(`<div class="kh-asst-toolbar"><h3>Çalışma Alanı</h3><div><button type="button" class="btn outline small" data-assistant-new>＋ Yeni Sohbet</button>${cutoff?'<button type="button" class="kh-history-link" data-assistant-history>Önceki Mesajlar</button>':''}</div></div>${selectCase()}<div class="kh-asst-tabs">${[['chat','Sohbet'],['files','Belgeler'],['sources','Kaynaklar']].map(x=>`<button type="button" class="${assistantTab===x[0]?'active':''}" data-assistant-tab="${x[0]}">${x[1]}</button>`).join('')}</div>${content}<div class="kh-asst-footnav">${btn('Görüntü Analizi','imaging','outline')}${btn('3D Simülasyon','simulation','outline')}</div><p class="kh-disclaimer">Bu tasarım çalışan sohbet kaydı içerir; klinik karar, tanı veya gerçek AI analizi üretmez. Kurgusal vaka bilgileri kullanın.</p>`)}`;
}
function filesPanel(){const files=storedFiles.filter(f=>f.case_id===caseId);return `<h3 class="sectiontitle">Vaka Görüntüleri ve Belgeleri</h3>${card(`<div class="notice"><strong>Deneme dosyaları</strong><p>PDF, JPEG, PNG ve DICOM dosyalarını en fazla 6 MB olacak şekilde yerel olarak kaydedebilirsiniz. Yalnızca kurgusal veriler yükleyin. Otomatik görüntü analizi yapılmaz.</p></div><form data-form="upload"><div class="field"><label>Örnek görüntü / PDF seçin</label><input name="attachment" type="file" accept=".pdf,.png,.jpg,.jpeg,.dcm,application/dicom" required></div><button class="btn">Dosyayı Bu Vakaya Ekle</button></form><div class="list">${files.map(x=>`<div class="item row"><div><b>${esc(x.filename)}</b><p class="mini">${Math.ceil(x.size/1024)} KB · ${esc(x.created_at)}</p></div><a class="btn outline small" href="/api/attachment/${x.id}" target="_blank" rel="noopener">Aç ↗</a></div>`).join('')||'<p class="muted">Bu vaka için yüklenen deneme dosyası yok.</p>'}</div>`)}`}
async function uploadFile(input,case_id=''){try{const file=input.files?.[0];if(!file)throw Error('Dosya seçilmedi');if(file.size>6000000)throw Error('En fazla 6 MB yüklenebilir');let mime=file.name.toLowerCase().endsWith('.dcm')?'application/dicom':file.type;if(!['application/pdf','image/png','image/jpeg','application/dicom'].includes(mime))throw Error('PDF, PNG, JPEG veya DICOM seçin');const bytes=new Uint8Array(await file.arrayBuffer());let out='';for(let i=0;i<bytes.length;i+=32768){out+=String.fromCharCode(...bytes.subarray(i,i+32768))}let r=await fetch('/api/attachments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,mime,case_id,base64:btoa(out)})});let j=await r.json();if(!r.ok)throw Error(j.error||'Dosya yüklenemedi');alert('Deneme dosyası kaydedildi');await loadFiles()}catch(e){alert(e.message)}}
function viewer(){const scale=imageZoom/100,stroke=Math.max(.2,imageOpacity/100);return `<div class="kh-image-scene"><svg viewBox="0 0 340 220" role="img" aria-label="Temsili çene anatomisi; gerçek tıbbi görüntü değildir"><defs><radialGradient id="clinicalJaw3"><stop offset="0" stop-color="#707A84"/><stop offset=".7" stop-color="#404B57"/><stop offset="1" stop-color="#202C39"/></radialGradient></defs><rect width="340" height="220" rx="12" fill="#17212e"/><g transform="translate(170 110) scale(${scale}) translate(-170 -110)"><path d="M60 47 Q106 22 170 53 Q230 23 280 55 Q299 113 264 166 Q226 200 165 190 Q103 198 73 158 Q43 104 60 47Z" fill="url(#clinicalJaw3)" stroke="#8995a3" stroke-width="2"/><path d="M82 66 Q117 57 166 79 Q229 52 262 77 Q268 116 243 153 Q210 176 169 172 Q116 175 89 145 Q74 108 82 66Z" fill="#273442" stroke="#6a7886" stroke-width="2"/><g fill="#bfc6ce" stroke="#828d99" stroke-width="1.3"><path d="M110 63 Q131 52 141 73 L139 106 L123 128 L110 106Z"/><path d="M150 72 Q167 60 180 75 L178 112 L164 132 L151 109Z"/><path d="M193 72 Q211 60 225 76 L221 116 L207 138 L193 112Z"/><g transform="rotate(35 240 119)"><path d="M226 88 Q247 75 257 98 L253 143 L239 161 L226 141Z"/></g></g>${imagingLayers.includes('bone')?`<path d="M60 47 Q106 22 170 53 Q230 23 280 55 Q299 113 264 166 Q226 200 165 190 Q103 198 73 158 Q43 104 60 47Z" fill="none" stroke="#22b68a" stroke-width="${3*stroke}" stroke-dasharray="7 4"/>`:''}${imagingLayers.includes('tooth')?`<g fill="none" stroke="#b18ae8" stroke-width="${3*stroke}"><path d="M110 63 Q131 52 141 73 L139 106 L123 128 L110 106Z"/><path d="M150 72 Q167 60 180 75 L178 112 L164 132 L151 109Z"/><path d="M193 72 Q211 60 225 76 L221 116 L207 138 L193 112Z"/><ellipse cx="240" cy="121" rx="22" ry="33" transform="rotate(35 240 121)"/></g>`:''}${imagingLayers.includes('nerve')?`<path d="M65 165 C100 144 121 173 163 158 S220 147 274 164" fill="none" stroke="#238be0" stroke-width="${5*stroke}" stroke-linecap="round"/>`:''}${imagingLayers.includes('risk')?`<circle cx="240" cy="150" r="23" fill="#f59e40" fill-opacity="${.12*stroke}" stroke="#f59e40" stroke-width="2" stroke-dasharray="5 3"/>`:''}</g><path d="M170 12 V208 M12 110 H328" stroke="#9aacbe" stroke-opacity=".35" stroke-dasharray="4 5"/><text x="12" y="207" font-size="9" fill="#b8ccdb">TEMSİLİ ANATOMİ · TANI AMAÇLI DEĞİL</text></svg></div>`}
function imaging(){const definitions=[['nerve','Mandibular Kanal','#238BE0','Kanalın diş kökleriyle ilişkisi, seyri ve kortikal ayrımı değerlendirilecek.'],['bone','Kortikal Kemik','#22B68A','Bukkal ve lingual kortikal sınırlar, süreklilik ve kemik kalınlığı incelenecek.'],['tooth','Diş ve Kökler','#B18AE8','Diş pozisyonu, kök morfolojisi ve komşu ikinci molar ilişkisi incelenecek.'],['risk','Yakınlık Bölgesi','#F59E40','Klinik olarak doğrulama gerektiren anatomik yakınlıklar değerlendirilecek.']];return `<div class="kh-imaging"><div class="kh-imaging-head"><div class="kh-imaging-brand"><span>✚</span><div><b>Kişisel Hekimim</b><small>AI KLİNİK ASİSTANI · 3.0</small></div></div><h2>Görüntü Analizi ve Klinik Değerlendirme</h2><p>Anatomik işaretlemeler, inceleme bulguları ve klinik planlama.</p></div><div class="kh-imaging-body"><div class="kh-imaging-context"><div><strong>${esc(current()?.subject||'Örnek Vaka · Gömülü 20 Yaş Dişi')}</strong><small>Kurgusal vaka · Temsili görüntü</small></div><span class="kh-imaging-badge">Demo</span></div>${selectCase()}<div class="kh-image-modality"><select id="khImageModality">${['CBCT','Panoramik Röntgen','BT','MR'].map(v=>`<option ${imageModality===v?'selected':''}>${v}</option>`).join('')}</select><button type="button" class="btn outline" data-image-upload>⇧ Görüntü Yükle</button></div><div class="kh-image-viewport"><div class="kh-viewport-cap"><span>${esc(imageModality)} · Anatomik görüntü alanı</span><small>Şematik görünüm</small></div>${viewer()}<div class="kh-viewport-tabs">${[['axial','Aksiyel'],['coronal','Koronal'],['sagittal','Sagittal'],['3d','3D']].map(([id,label])=>`<button class="${imageOrientation===id?'active':''}" data-image-orientation="${id}">${label}</button>`).join('')}</div><div class="kh-viewport-zoom"><button data-image-zoom="minus">−</button><span>${imageZoom}%</span><button data-image-zoom="plus">＋</button><button data-image-zoom="reset" title="Sıfırla">↶</button></div><p>Görünüm seçenekleri bu önizlemede aynı temsili şemayı gösteriyor. Gerçek DICOM kesitleri henüz açılmıyor.</p></div><section class="kh-imaging-card"><div class="kh-inline-title"><h3>Anatomik Katmanlar</h3><small>${imagingLayers.length}/4 aktif</small></div>${definitions.map(([id,label,color])=>`<label class="kh-image-layer"><span style="background:${color}"></span><b>${label}</b><input type="checkbox" data-layer="${id}" ${imagingLayers.includes(id)?'checked':''}></label>`).join('')}<div class="kh-image-opacity"><label for="imageOpacity">Katman saydamlığı</label><span>${imageOpacity}%</span></div><input id="imageOpacity" type="range" min="20" max="100" step="5" value="${imageOpacity}"></section><section class="kh-clinical"><h2>AI Klinik Değerlendirme</h2><div class="kh-clinical-tabs">${[['findings','Bulgular'],['planning','Planlama'],['sources','Kaynaklar']].map(([id,label])=>`<button class="${imageTab===id?'active':''}" data-image-tab="${id}">${label}</button>`).join('')}</div>${imageTab==='findings'?`<div class="kh-clinical-summary"><strong>▤ Anatomik İnceleme</strong><p>Gerçek görüntüler işlendiğinde otomatik bulgular ve doğrulama gerektiren yapılar burada gösterilecek.</p></div>${definitions.map(([id,label,color,desc])=>`<div class="kh-finding"><button data-image-expand="${id}"><i style="background:${color}"></i><b>${label}</b><span>${imageExpanded===id?'⌃':'⌄'}</span></button>${imageExpanded===id?`<p>${desc}</p><label><input type="checkbox" data-image-review="${id}" ${imageReviewed.includes(id)?'checked':''}> Hekim tarafından incelendi</label>`:''}</div>`).join('')}<p class="kh-reviewed">İncelenen başlık: ${imageReviewed.length}/4</p>`:imageTab==='planning'?`<div class="kh-clinical-summary"><strong>⇄ Klinik Seçenekler ve Ölçümler</strong><div class="kh-clinical-tabs kh-measures">${[['distance','Mesafe'],['angle','Açı'],['thickness','Kalınlık']].map(([id,label])=>`<button class="${imageMeasure===id?'active':''}" data-image-measure="${id}">${label}</button>`).join('')}</div><p>${imageMeasure==='distance'?'Anatomik yapılar arasındaki mesafeler':imageMeasure==='angle'?'Diş ve yapıların açısal konumları':'Kortikal kemik kalınlıkları'} kalibre edilmiş görüntüler üzerinden ölçülebilecek.</p><span class="kh-imaging-badge">Gerçek ölçüm bulunmuyor</span></div><label class="kh-note-label">Hekim planlama notları</label><textarea id="khImageNotes" rows="4" placeholder="Anatomik bulgular ve planlama notları...">${esc(imageNotes)}</textarea><button class="btn" data-image-save-notes>Notu Vaka Dosyasına Kaydet</button>`:`<div class="kh-clinical-summary"><strong>▤ Bilimsel Kaynaklar</strong><p>Vaka ile ilgili güncel klinik kılavuzlar, araştırmalar, kanıt düzeyleri ve doğrulanabilir bağlantılar burada listelenecek.</p><span class="kh-imaging-badge">Canlı literatür taraması yapılmadı</span></div>`}</section><div class="kh-imaging-safety"><b>⚠ Klinik Güvenlik</b><p>Bu anatomik çizim temsilidir; gerçek hastanın sinir, kök veya kemik sınırlarını göstermez. Tanı veya tedavi amacıyla kullanılmaz.</p></div>${filesPanel()}</div></div>`}
function simSvg(plan='A',compact=false){
 const mode=simView==='front'?'translate(0 18) scale(1 .77)':simView==='side'?'translate(16 0) scale(.82 1)':'';
 const scale=compact?1:simZoom/100,rotation=compact?0:simRotation;
 const c=plan==='A'?[235,131,5]:[256,139,16];
 const teeth=[{x:77,y:95,a:-24},{x:118,y:83,a:-14},{x:162,y:91,a:-4},{x:207,y:89,a:6},{x:252,y:81,a:15},{x:297,y:94,a:27}];
 return `<svg viewBox="0 0 380 280" class="kh-sim-svg" role="img" aria-label="Temsili çene anatomisi, gerçek hasta verisi veya hacimsel rekonstrüksiyon değil"><defs><linearGradient id="jawbone4" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#9AD9C8"/><stop offset=".55" stop-color="#368D89"/><stop offset="1" stop-color="#245B68"/></linearGradient><linearGradient id="tooth4" x1="0" y1="0" x2=".7" y2="1"><stop stop-color="#fff"/><stop offset=".55" stop-color="#CBD7E1"/><stop offset="1" stop-color="#8297A9"/></linearGradient><linearGradient id="implant4" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#FFDB9E"/><stop offset=".5" stop-color="#E99737"/><stop offset="1" stop-color="#AF6319"/></linearGradient></defs><rect width="380" height="280" rx="12" fill="#172634"/><g stroke="#55707D" stroke-width=".6" opacity=".2">${Array.from({length:12},(_,i)=>`<path d="M${i*35} 0 V280 M0 ${i*28} H380"/>`).join('')}</g><g transform="translate(190 145) scale(${scale}) translate(-190 -145)"><g transform="${mode} rotate(${rotation} 190 145)">${simLayers.includes('bone')?`<path d="M44 105 C63 63 125 61 160 89 C188 103 200 97 230 79 C279 51 342 82 341 136 C339 192 298 228 248 239 C204 248 168 247 125 235 C80 221 38 181 44 105Z" fill="url(#jawbone4)" fill-opacity="${simOpacity/100}" stroke="#8AD7C8" stroke-width="2"/><path d="M57 119 C87 101 128 105 161 123 C187 137 210 127 237 108 C271 91 321 103 327 138" stroke="#B8EADA" stroke-width="5" opacity=".4" fill="none"/>`:''}${simLayers.includes('teeth')?`<g fill="url(#tooth4)" stroke="#8599AB" stroke-width="1.5" opacity="${simOpacity/100}">${teeth.map(t=>`<g transform="translate(${t.x} ${t.y}) rotate(${t.a})"><path d="M-16 -16 Q-23 -9 -18 7 L-10 22 L-8 45 Q-3 55 0 48 Q3 55 8 45 L11 22 Q20 5 16 -14 Q0 -27 -16 -16Z"/><path d="M-14 8 Q0 20 14 8" stroke="#8199AA" fill="none" opacity=".6"/></g>`).join('')}</g>`:''}${simLayers.includes('nerve')?'<path d="M65 183 C110 171 137 208 190 202 C246 195 275 164 313 174" fill="none" stroke="#399CFF" stroke-width="7" stroke-linecap="round" stroke-dasharray="10 3"/>':''}${simLayers.includes('implant')?`<g transform="translate(${c[0]} ${c[1]}) rotate(${c[2]})"><rect x="-9" y="-20" width="18" height="72" rx="5" fill="url(#implant4)" stroke="#FBD9A7" stroke-width="1.4"/>${Array.from({length:6},(_,i)=>`<path d="M-9 ${i*9-8} L9 ${i*9-2}" stroke="#915321" stroke-width="2"/>`).join('')}<path d="M-16 -26 H16 L11 -16 H-11Z" fill="#E7B46A" stroke="#FFE0B0" stroke-width="1.5"/></g><circle cx="${c[0]}" cy="${c[1]+58}" r="21" fill="#F4A044" fill-opacity=".12" stroke="#F4A044" stroke-dasharray="4 4"/>`:''}</g></g><text x="12" y="18" fill="#C9DEE8" font-size="10">VIEW: ${esc(simView.toUpperCase())}</text><text x="12" y="266" fill="#C9DEE8" font-size="10">ŞEMATİK · KLİNİK MODEL DEĞİL</text>${compact?'':`<text x="294" y="266" fill="#C9DEE8" font-size="10">ZOOM ${simZoom}%</text>`}</svg>`;
}
function simulation(){
 const c=current(),plan=state.case_plans.find(p=>p.case_id===caseId&&p.scenario===simScenario);
 const layers=[['bone','Çene kemiği','#70CDB4'],['teeth','Diş ve kökler','#E2E8EF'],['nerve','Mandibular kanal','#409FFF'],['implant','Planlanan implant','#F7A14B']];
 const tabs=[['model','3D Model'],['planning','Planlama'],['comparison','Karşılaştır']];
 const tabrow=`<div class="kh-sim-tabs">${tabs.map(([id,label])=>`<button type="button" class="${simTab===id?'active':''}" data-sim-tab="${id}">${label}</button>`).join('')}</div>`;
 let content='';
 if(simTab==='model') content=`<div class="kh-sim-viewer"><div class="kh-sim-viewer-head"><span>ANATOMİK MODEL GÖRÜNTÜLEYİCİ</span><small>Temsili 3D görünüm</small></div><div class="kh-sim-scene">${simSvg(simScenario)}</div><div class="kh-sim-viewtabs">${[['iso','İzometrik'],['front','Önden'],['side','Yandan']].map(([id,label])=>`<button type="button" data-sim-view="${id}" class="${simView===id?'active':''}">${label}</button>`).join('')}</div><div class="kh-sim-controls"><button type="button" data-sim-control="rotate">↶ Döndür</button><button type="button" data-sim-control="minus">−</button><span>${simZoom}%</span><button type="button" data-sim-control="plus">＋</button><button type="button" data-sim-control="reset">↺ Sıfırla</button></div></div><div class="kh-sim-card"><h3>Anatomik Katmanlar <small>${simLayers.length} aktif</small></h3>${layers.map(([id,label,color])=>`<label class="kh-sim-layer"><i style="background:${color}"></i><strong>${label}</strong><input type="checkbox" data-sim-layer="${id}" ${simLayers.includes(id)?'checked':''}></label>`).join('')}<div class="kh-sim-range-label"><label for="khSimOpacity">Model saydamlığı</label><span>${simOpacity}%</span></div><input id="khSimOpacity" type="range" min="20" max="100" step="5" value="${simOpacity}"/></div>`;
 else if(simTab==='planning')content=`<div class="kh-sim-card"><h2>İşlem Planlama</h2><p class="muted">Bir senaryo seçerek temsili implant konumunu değiştirebilirsin.</p>${[['A','Plan A — Standart yerleşim','Temsili dik implant yerleşimi'],['B','Plan B — Alternatif açı','Temsili açılı yerleşim']].map(([id,title,desc])=>`<label class="kh-sim-choice"><input type="radio" name="khSimScenario" value="${id}" ${simScenario===id?'checked':''}><span><b>${title}</b><small>${desc}</small></span></label>`).join('')}</div><div class="kh-sim-card"><h3>⌗ Ölçüm ve Planlama Araçları</h3><div class="kh-sim-tools">${['Mesafe ölçümü','Açı ölçümü','İmplant konumu','Kritik yapı kontrolü'].map(t=>`<div><b>${t}</b><small>Geliştirilecek</small></div>`).join('')}</div></div><div class="kh-sim-card"><form data-form="plan"><input type="hidden" name="scenario" value="${simScenario}"><label for="plan_note">Hekim planlama notları</label><textarea name="plan_note" id="plan_note" rows="5" placeholder="Kurgusal vaka için planlama notları...">${esc(plan?.plan_note||'')}</textarea><div class="kh-sim-actions"><button class="btn" type="submit">◫ Notu Vaka Dosyasına Kaydet</button><button class="btn outline" type="button" data-sim-tab="model">Modelde Göster</button></div></form></div>`;
 else content=`<div class="kh-sim-card"><h2>Tedavi Planlarını Karşılaştır</h2><p class="muted">Her iki temsili yerleşimi yan yana incele. Klinik sonuç tahmini değildir.</p><div class="kh-sim-comparison">${[['A','Plan A','Dik yerleşim'],['B','Plan B','Açılı yerleşim']].map(([id,label,desc])=>`<div class="kh-sim-compare-item ${simScenario===id?'chosen':''}"><h3>${label}</h3><div class="kh-sim-smallview">${simSvg(id,true)}</div><b>${desc}</b><small>${id==='A'?'Standart konum':'Alternatif konum'}</small><button class="btn outline" type="button" data-sim-show="${id}">Modelde Gör</button></div>`).join('')}</div></div><div class="kh-sim-card"><h3>Karşılaştırma Kriterleri</h3><table class="kh-sim-table"><tr><th>Kriter</th><th>Plan A</th><th>Plan B</th></tr><tr><td>Yönelim</td><td>Dik</td><td>Açılı</td></tr><tr><td>Sayısal ölçüm</td><td>Yok</td><td>Yok</td></tr><tr><td>Klinik risk</td><td>Değerlendirilmedi</td><td>Değerlendirilmedi</td></tr></table></div>`;
 return `<div class="kh-sim"><header class="kh-sim-head"><div class="kh-sim-brand"><span>✚</span><div><b>Kişisel Hekimim</b><small>HEKİM PANELİ · 3.0</small></div><span class="kh-sim-online">● Çevrim içi</span></div><h1>3D Simülasyon ve Tedavi Planlama</h1><p>Anatomik modelleme · İşlem senaryoları · Karşılaştırmalı değerlendirme</p></header><div class="kh-sim-body"><div class="kh-sim-case"><div><b>${esc(c?.subject||'Örnek Vaka 001')}</b><small>${esc(c?.specialty||'Diş Hekimliği')} · Kurgusal vaka</small></div><span class="kh-sim-badge">Demo</span></div>${selectCase()}<div class="field"><label>Uzmanlık alanı</label><select id="khSimSpecialty"><option>Diş Hekimliği / Çene Cerrahisi</option><option>Ortodonti</option><option>Ortopedi (gelecek modül)</option><option>Diğer branşlar (gelecek modüller)</option></select></div>${tabrow}${content}<div class="kh-sim-safety"><strong>⚠ Önizleme hakkında</strong><p>Bu, gerçek bir hasta görüntüsünden oluşturulmuş 3D model değildir. Döndürme ve yakınlaştırma yalnızca çizimin görsel dönüşümleridir. Hacimsel rekonstrüksiyon, klinik ölçüm, cerrahi güvenlik veya tedavi sonucu hesaplanmaz. Gerçek hasta verisi girmeyin.</p></div></div></div>`;
}
let stage5Tab='network',stage5RequestFilter='all',stage5Type='written',stage5Target='',stage5Case='',stage5Message='';
function s5Status(s){return ({pending:'Bekliyor',accepted:'İnceleniyor',rejected:'Reddedildi',replied:'Yanıtlandı'})[s]||s}
function s5Doctor(d){return `${esc(d.title||'Dr.')} ${esc(d.full_name)}`}
function s5Tabs(){return `<div class="s5-tabs" role="tablist"><button data-s5-tab="network" class="${stage5Tab==='network'?'selected':''}">♧ Hekim Ağı</button><button data-s5-tab="requests" class="${stage5Tab==='requests'?'selected':''}">▤ Konsültasyon</button><button data-s5-tab="new" class="${stage5Tab==='new'?'selected':''}">＋ Yeni Talep</button></div>`}
function s5Header(){let c=networkState.connections||[],p=peerState.consults||[],id=peerState.self_id;return `<div class="s5-intro"><div><span class="s5-eyebrow">KİŞİSEL HEKİMİM 3.0 · HEKİM ÇALIŞMA ALANI</span><h2>Hekim Ağı ve Konsültasyon</h2><p>Meslektaşlarını keşfet, bağlantı kur ve klinik soruları güvenli bir iş akışında yönet.</p></div><span class="s5-demo-tag">● Yerel demo · Mesleki doğrulama yok</span></div><div class="s5-stats"><div><span>♧</span><strong>${c.filter(x=>x.status==='accepted').length}</strong><small>Bağlantılarım</small></div><div><span>▤</span><strong>${p.filter(x=>x.recipient_id===id&&x.status==='pending').length}</strong><small>Bekleyen talepler</small></div><div><span>↗</span><strong>${p.filter(x=>x.sender_id===id).length}</strong><small>Gönderilen talepler</small></div></div>`}
function s5Network(){const ns=networkState,all=ns.doctors||[],relations=ns.connections||[],self=ns.self_id;const specialties=[...new Set(all.map(d=>d.specialty||d.profession||'Diğer'))];const shown=all.filter(d=>(networkSpecialty==='all'||(d.specialty||d.profession||'Diğer')===networkSpecialty)&&`${d.full_name} ${d.specialty||''} ${d.city||''} ${d.institution||''}`.toLocaleLowerCase('tr').includes(networkSearch.toLocaleLowerCase('tr')));const rel=(id)=>relations.find(x=>(x.requester_id===self&&x.recipient_id===id)||(x.recipient_id===self&&x.requester_id===id));const cardDoc=d=>{let r=rel(d.id),initials=d.full_name.split(' ').slice(0,2).map(a=>a[0]).join('').toUpperCase();return `<article class="s5-doctor"><div class="s5-doctor-head"><span class="s5-avatar">${esc(initials)}</span><div><h3>${s5Doctor(d)}</h3><b>${esc(d.specialty||d.profession||'Hekim')}</b><p>⌖ ${esc(d.city||'Şehir belirtilmedi')} · ${esc(d.institution||'Kurum belirtilmedi')}</p></div></div><p class="s5-bio">${esc(d.biography||'Mesleki tanıtım henüz eklenmedi.')}</p><div class="s5-actions"><button class="s5-outline" data-network-view="${d.id}">Profili Gör</button>${r?.status==='accepted'?`<span class="s5-relation">✓ Bağlantıda</span>`:r?.status==='pending'?`<span class="s5-relation">◷ ${r.requester_id===self?'İstek gönderildi':'Yanıt bekliyor'}</span>`:`<button data-connect="${d.id}" class="s5-teal">＋ Bağlantı İste</button>`}${d.accepting?`<button class="s5-outline" data-network-consult="${d.id}">Görüş İste ↗</button>`:''}</div></article>`};let pending=relations.filter(x=>x.recipient_id===self&&x.status==='pending');return `<div class="s5-row"><h3>Uzman Hekimleri Keşfet</h3><button class="s5-outline" data-page="profile">Profilimi Düzenle</button></div><div class="s5-search"><label><span>⌕</span><input id="networkSearch" placeholder="Hekim, branş veya şehir ara..." value="${esc(networkSearch)}"></label><select id="networkSpecialty"><option value="all">Tüm uzmanlıklar</option>${specialties.map(x=>`<option value="${esc(x)}" ${networkSpecialty===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="s5-doctor-grid">${shown.map(cardDoc).join('')||'<div class="s5-empty">Aramanıza uygun görünür hekim bulunamadı. İkinci bir hekim hesabı ile ağ özelliğini deneyebilirsiniz.</div>'}</div><div class="s5-row s5-subheading"><h3>Gelen Bağlantı İstekleri</h3><span class="s5-muted">${pending.length} bekleyen</span></div>${pending.map(x=>`<div class="s5-request-line"><span class="s5-avatar">DR</span><div><strong>${esc(x.requester_name)}</strong><small>Bağlantı kurmak istiyor</small></div><button class="s5-teal" data-connection="${x.id}" data-answer="accepted">Kabul Et</button><button class="s5-outline" data-connection="${x.id}" data-answer="rejected">Reddet</button></div>`).join('')||'<div class="s5-empty">Henüz gelen bağlantı isteği yok.</div>'}${networkSelected?(()=>{const d=all.find(x=>x.id===networkSelected);return d?`<div class="s5-overlay"><section class="s5-modal"><button class="s5-close" data-network-close="1">×</button><span class="s5-avatar">${esc(d.full_name.slice(0,2).toUpperCase())}</span><h2>${s5Doctor(d)}</h2><p>${esc(d.specialty||'Hekim')} · ${esc(d.city||'')}</p><h3>Hakkında</h3><p>${esc(d.biography||'Henüz tanıtım eklenmedi.')}</p><p class="s5-muted">Bu yerel demoda diplomalar ve uzmanlık bilgileri doğrulanmaz.</p><button class="s5-teal" data-network-close="1">Kapat</button></section></div>`:''})():''}`}
function s5Requests(){const me=peerState.self_id,rows=(peerState.consults||[]).filter(x=>stage5RequestFilter==='all'||(stage5RequestFilter==='incoming'?x.recipient_id===me:x.sender_id===me));return `<div class="s5-row"><h3>Konsültasyon Talepleri</h3><button class="s5-teal" data-s5-tab="new">＋ Yeni Talep</button></div><div class="s5-filters">${[['all','Tümü'],['incoming','Gelen'],['outgoing','Gönderilen']].map(([id,name])=>`<button class="${stage5RequestFilter===id?'active':''}" data-s5-filter="${id}">${name}</button>`).join('')}</div><div class="s5-request-grid">${rows.map(r=>{const mine=r.sender_id===me;return `<article class="s5-consult"><div class="s5-row"><strong>${esc(mine?r.recipient_name:r.sender_name)}</strong><span class="s5-chip status-${esc(r.status)}">${s5Status(r.status)}</span></div><small>${mine?'↗ Gönderilen':'↙ Gelen'} · ${r.consult_type==='video'?'Görüntülü görüşme talebi':'Yazılı uzman görüşü'} · ${esc(r.created_at)}</small><h4>${esc(r.subject)}</h4><p>${esc(r.question)}</p>${r.case_ref?`<small>Vaka referansı: ${esc(r.case_ref)} (hasta verisi paylaşılmadı)</small>`:''}${r.status==='pending'&&!mine?`<div class="s5-actions"><button class="s5-teal" data-peer-id="${r.id}" data-peer-status="accepted">İncelemeye Al</button><button class="s5-outline" data-peer-id="${r.id}" data-peer-status="rejected">Reddet</button></div>`:''}${r.status==='accepted'&&!mine?`<form data-form="peerreply" class="s5-reply"><input type="hidden" name="id" value="${r.id}"><label>Uzman görüşü taslağı</label><textarea name="response" required minlength="5" maxlength="4000" placeholder="Bu kurgusal vakaya ilişkin değerlendirmenizi yazın..."></textarea><button class="s5-teal">Görüşü Yanıtla</button></form>`:''}${r.response?`<div class="s5-response"><strong>Uzman yanıtı</strong><p>${esc(r.response)}</p></div>`:''}</article>`}).join('')||'<div class="s5-empty">Bu kategoride henüz bir talep bulunmuyor.</div>'}</div>`}
function s5New(){const docs=(networkState.doctors||[]).filter(x=>x.accepting);if(!stage5Target&&docs.length)stage5Target=String(docs[0].id);return `<h3>Yeni Konsültasyon Talebi</h3><p class="s5-muted">Karşı hekime yalnızca yazdığınız klinik soru gönderilir. Dosyalar ve hasta kayıtları otomatik paylaşılmaz.</p>${docs.length?`<form data-form="peerrequest" class="s5-form"><div class="s5-formgrid"><label>Görüş istenecek hekim<select name="recipient_id" id="s5Target" required>${docs.map(d=>`<option value="${d.id}" ${String(d.id)===stage5Target?'selected':''}>${s5Doctor(d)} — ${esc(d.specialty||'Hekim')}</option>`).join('')}</select></label><label>Yerel vaka referansı (isteğe bağlı)<select name="case_ref"><option value="">Vaka seçme</option>${state.cases.map(c=>`<option value="${esc(c.id)}" ${stage5Case===c.id?'selected':''}>${esc(c.id)} · ${esc(c.subject)}</option>`).join('')}</select></label></div><div class="s5-formgrid"><label>Görüş türü<select name="consult_type"><option value="written">Yazılı uzman görüşü</option><option value="video">Görüntülü görüşme talebi (video bağlantısı yok)</option></select></label><label>Konsültasyon konusu<input name="subject" required maxlength="160" placeholder="Klinik değerlendirme konusu"></label></div><label>Klinik soru<textarea name="question" required minlength="5" maxlength="3000" placeholder="Kişisel sağlık bilgisi içermeyen örnek vaka sorunuz..."></textarea></label><div class="s5-privacy"><strong>⛨ Veri paylaşım kontrolü</strong><p>Bu demo, dosya aktarımı veya gerçek görüntülü görüşme sağlamaz. Gerçek hasta verileri girmeyin.</p></div><button class="s5-teal s5-submit" type="submit">↗ Görüş Talebini Gönder</button></form>`:`<div class="s5-empty">Konsültasyona açık başka bir hekim bulunamadı. İkinci hekim hesabı oluşturup profil ayarlarında görünürlük ve görüş kabulünü açın.</div>`}`}
function s5Page(){return `<div class="s5-shell">${s5Header()}<section class="s5-surface">${s5Tabs()}<div class="s5-content">${stage5Tab==='network'?s5Network():stage5Tab==='requests'?s5Requests():s5New()}</div></section><p class="s5-footer">Bu yerel tasarım ve iş akışı demosudur. Hekim mesleki yetkileri doğrulanmaz; gerçek hasta verileri kullanılmamalıdır.</p></div>`}
function consult(){return s5Page()}
function reports(){const request=state.requests.find(x=>String(x.id)===String(chosenReport))||state.requests[0],r=state.clinical_reports.find(x=>x.request_id===request?.id);return `${card(`<h3>Uzman Görüş Raporları · Yalnızca Taslak</h3><p class="muted">Elektronik imza, hekim kimlik doğrulaması ve resmî gönderim bulunmaz. Bu alan, rapor formunu ve vaka bağlantısını denemek içindir.</p><div class="field"><label>Konsültasyon kaydı</label><select id="reportSelect">${state.requests.map(x=>`<option value="${x.id}" ${x.id===request?.id?'selected':''}>#${x.id} · ${esc(x.expert)} · ${esc(x.case_id)}</option>`).join('')}</select></div>${request?`<div class="notice"><b>Danışma sorusu</b><p>${esc(request.question)}</p></div><form data-form="report"><input type="hidden" name="request_id" value="${request.id}">${field('İncelenen bulgular','findings',r?.findings||'','textarea')}${field('Uzman değerlendirme taslağı','assessment',r?.assessment||'','textarea')}${field('Alternatif yaklaşımlar','options',r?.options||'','textarea')}${field('Riskler ve belirsizlikler','risks',r?.risks||'','textarea')}${field('Kaynaklar / literatür notları','literature',r?.literature||'','textarea')}<button class="btn">Rapor Taslağını Kaydet</button></form><p class="muted mini">Taslak kaydedilir; uzman tarafından imzalanmış veya gönderilmiş rapor değildir.</p>`:'<p class="muted">Rapor hazırlamak için önce konsültasyon taslağı oluşturun.</p>'}`)}`}
let networkTab='discover',networkSearch='',networkSpecialty='all',networkSelected=null;
function network(){return s5Page()}
async function loadNetwork(){try{let r=await fetch('/api/network');if(r.ok)networkState=await r.json();if(page==='network')render()}catch(e){console.warn(e)}}
function patients(){return `${card(`<h3>Hastalarım · Örnek Dosyalar</h3><div class="list">${state.cases.map(c=>`<div class="item"><div class="row"><div><b>${esc(c.patient)}</b><p>${esc(c.id)} · ${esc(c.subject)} · ${esc(c.specialty)}</p></div><button class="btn small" data-open-case="${esc(c.id)}">Dosyayı Aç</button></div></div>`).join('')}</div>`)}`}
function calendar(){return `${card(`<div class="row"><h3>Randevularım</h3><span class="badge">Yerel demo</span></div><div class="list">${state.appointments.map(a=>`<div class="item"><div class="row"><div><b>${esc(a.person)}</b><p>${esc(a.date)} · ${esc(a.type)}</p><span class="badge ${a.status==='bekliyor'?'warn':''}">${esc(a.status)}</span></div>${a.status==='bekliyor'?`<div class="btnrow"><button class="btn small" data-appointment="${a.id}" data-status="onaylandı">Onayla</button><button class="btn small outline" data-appointment="${a.id}" data-status="reddedildi">Reddet</button></div>`:''}</div></div>`).join('')}</div>`)}<h3 class="sectiontitle">Örnek Randevu Oluştur</h3>${card(`<form data-form="appointment">${field('Hasta / hekim adı','person')}${field('Tarih ve saat','date','','datetime-local')}<div class="field"><label>Görüşme türü</label><select name="type"><option>Yüz yüze</option><option>Çevrim içi</option><option>Konsültasyon</option></select></div><button class="btn">Taslak Randevu Oluştur</button></form>`)}<h3 class="sectiontitle">Çalışma Günleri ve Randevu Ayarları</h3>${card(`<form data-form="schedule"><p class="muted">Çalışma saatleri uygulamaya kaydedilir. Bu ayarlar yerel randevu taleplerini düzenlemek için kullanılır.</p><div class="pills">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map((name,i)=>`<label class="pill"><input type="checkbox" name="day_${i}" ${String(state.schedule?.days||'0,1,2,3,4').split(',').includes(String(i))?'checked':''}> ${name}</label>`).join('')}</div><div class="formgrid">${field('Başlangıç','start_time',state.schedule?.start_time||'09:00','time')}${field('Bitiş','end_time',state.schedule?.end_time||'17:00','time')}</div><div class="field"><label>Randevu süresi</label><select name="duration">${[15,30,45,60].map(n=>`<option ${state.schedule?.duration===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Görüşme türü</label><select name="visit_type">${[['both','Yüz yüze ve çevrim içi'],['physical','Yüz yüze'],['online','Çevrim içi']].map(([v,label])=>`<option value="${v}" ${state.schedule?.visit_type===v?'selected':''}>${label}</option>`).join('')}</select></div><label class="layer">Talepleri otomatik onaylama tercihi <input type="checkbox" name="auto_confirm" ${state.schedule?.auto_confirm?'checked':''}></label><p class="mini muted">Otomatik onay özelliği henüz gerçek randevu tahsis sistemine bağlı değildir.</p><button class="btn">Çalışma Saatlerini Kaydet</button></form>`)}`}
function notifications(){let req=state.requests.length, wait=state.appointments.filter(a=>a.status==='bekliyor').length;return `${card(`<h3>Bildirim Merkezi</h3><div class="grid three"><div class="kpi"><span class="smallcaps">Konsültasyon Taslağı</span><div class="big">${req}</div></div><div class="kpi"><span class="smallcaps">Bekleyen Randevu</span><div class="big">${wait}</div></div><div class="kpi"><span class="smallcaps">Hekim Rehberi</span><div class="big">${state.contacts.length}</div></div></div><h3 class="sectiontitle">Hasta Panelinden Gelen Talepler</h3><div class="list">${(state.patient_requests||[]).map(r=>`<div class="item"><b>${esc(r.patient_name)}</b> <span class="badge">${esc(r.status)}</span><p>${esc(r.kind==='opinion'?'Uzman görüşü':'Randevu')} · ${esc(r.specialty)} — ${esc(r.message)}</p>${r.status==='bekliyor'?`<button class="btn small" data-patient-request="${r.id}">İncelemeye Al</button>`:''}</div>`).join('')||'<p class="muted">Henüz talep yok.</p>'}</div><h3 class="sectiontitle">Gelişmeler</h3><div class="item">♧ ${req} konsültasyon taslağı kaydedildi.</div><div class="item">▦ ${wait} örnek randevu karar bekliyor.</div><div class="item">♙ ${state.contacts.length} örnek hekim kaydı bulunuyor.</div><p class="muted mini">Canlı bildirim sistemi ve dış mesajlaşma yoktur.</p>`)}`}
function profile(){const p=state.profile||{},u=state.user||{};return `${card(`<div class="row"><div><div class="ic">♙</div><h2>${esc(u.full_name||'Hekim')}</h2><p>${esc(p.specialty||p.profession||'Meslek bilgisi girilmedi')}</p></div><span class="badge warn">Doğrulanmamış hekim hesabı</span></div><p class="muted">Profesyonel profilim · Mesleki bilgiler burada beyan edilir; diploma ve uzmanlık doğrulaması henüz yapılmaz.</p><form data-form="userprofile"><div class="formgrid">${field('Ad soyad','full_name',u.full_name||'')}${field('Unvan','title',p.title||'')}${field('Meslek (Tıp / Diş Hekimliği)','profession',p.profession||'')}${field('Uzmanlık / çalışma alanı','specialty',p.specialty||'')}${field('Şehir','city',p.city||'')}${field('Kurum','institution',p.institution||'')}${field('Üniversite / eğitim','school',p.school||'')}</div>${field('Mesleki deneyim','experience',p.experience||'','textarea')}${field('Hakkımda','biography',p.biography||'','textarea')}${field('Akademik çalışmalar','publications',p.publications||'','textarea')}<div class="field"><label>Diğer hekimlere profil görünürlüğü</label><select name="visibility">${[['private','Gizli'],['connections','Sadece bağlantılarım (yakında)'],['verified','Diğer yerel hekim hesaplarına açık (demo)']].map(([v,l])=>`<option value="${v}" ${p.visibility===v?'selected':''}>${l}</option>`).join('')}</select></div><label class="layer">Konsültasyon taleplerine açığım <input name="accepting" type="checkbox" ${p.accepting?'checked':''}></label><label class="layer">Bildirim tercihleri açık <input name="notify" type="checkbox" ${p.notify?'checked':''}></label><button class="btn">Profili Kaydet</button></form>`)}${card(`<h3>Mesleki Ağ</h3><p>Diğer hekim hesaplarını bul, bağlantı isteği gönder ve kendi rehberini yönet.</p>${btn('Hekim Ağına Git','network','secondary')}`)}`}
function settings(){return `${card(`<h2>Görünüm ve Güvenlik</h2><div class="formgrid"><div class="field"><label>Tema</label><select id="theme">${[['teal','Turkuaz'],['blue','Mavi'],['purple','Mor'],['dark','Koyu']].map(([v,l])=>`<option value="${v}" ${theme===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Yazı boyutu</label><select id="font">${[['small','Küçük'],['normal','Normal'],['large','Büyük']].map(([v,l])=>`<option value="${v}" ${font===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="notice">Çevrim içi göstergesi arayüz durumudur. Gerçek hekim uygunluğunu veya başka cihazlarla bağlantıyı göstermez.</div>`)}${card(`<h3>Şifremi Değiştir</h3><form data-form="password">${field('Mevcut parola','current','','password')}${field('Yeni parola (en az 8 karakter)','new','','password')}<button class="btn">Parolayı Değiştir</button></form><p class="mini muted">Parola değiştirildiğinde güvenlik için yeniden giriş gerekir.</p>`)}${card(`<h3>Veri Güvenliği ve Sınırlar</h3><p>Veriler bu bilgisayardaki yerel SQLite dosyasına kaydedilir. Uygulama gerçek klinik kullanım, elektronik imza, resmi uzaktan sağlık hizmeti veya mevzuat uyum sertifikası sunmaz. Gerçek hasta verisi girmeyin.</p><p>Veritabanı klasörü: uygulamanın yanında <code>demo.db</code> olarak oluşur. Yedeklemek için uygulama kapalıyken bu dosyayı kopyalayın.</p>`)}`}
function render(){document.documentElement.style.setProperty('--main',palettes[theme]);document.documentElement.style.setProperty('--soft',theme==='dark'?'#e8eff2':theme==='purple'?'#f0eafb':theme==='blue'?'#e7f0fc':'#e7f5f2');document.body.style.fontSize=font==='large'?'16px':font==='small'?'12px':'14px';nav();const map={home,case:casePage,assistant,imaging,simulation,consult,network,patients,calendar,notifications,profile,reports,settings};el('content').innerHTML=(map[page]||home)();const ch=el('chatbox');if(ch)ch.scrollTop=ch.scrollHeight}
function onClick(e){const s5=e.target.closest('[data-s5-tab],[data-s5-filter]');if(s5){if(s5.dataset.s5Tab){stage5Tab=s5.dataset.s5Tab}else{stage5RequestFilter=s5.dataset.s5Filter}networkSelected=null;render();return}const st=e.target.closest('[data-sim-tab],[data-sim-view],[data-sim-control],[data-sim-show]');if(st){if(st.dataset.simTab){simTab=st.dataset.simTab}else if(st.dataset.simView){simView=st.dataset.simView}else if(st.dataset.simShow){simScenario=st.dataset.simShow;simTab='model'}else if(st.dataset.simControl){const x=st.dataset.simControl;if(x==='rotate')simRotation-=20;else if(x==='plus')simZoom=Math.min(150,simZoom+25);else if(x==='minus')simZoom=Math.max(75,simZoom-25);else{simRotation=0;simZoom=100;simView='iso'}}render();return}const im=e.target.closest('[data-image-tab],[data-image-orientation],[data-image-zoom],[data-image-expand],[data-image-measure],[data-image-upload],[data-image-save-notes]');if(im){if(im.dataset.imageTab){imageTab=im.dataset.imageTab;render()}else if(im.dataset.imageOrientation){imageOrientation=im.dataset.imageOrientation;render()}else if(im.dataset.imageZoom){imageZoom=im.dataset.imageZoom==='plus'?Math.min(150,imageZoom+25):im.dataset.imageZoom==='minus'?Math.max(75,imageZoom-25):100;render()}else if(im.dataset.imageExpand){imageExpanded=imageExpanded===im.dataset.imageExpand?'':im.dataset.imageExpand;render()}else if(im.dataset.imageMeasure){imageMeasure=im.dataset.imageMeasure;render()}else if(im.hasAttribute('data-image-upload')){document.querySelector('.kh-imaging [data-form=upload] input[type=file]')?.click();document.querySelector('.kh-imaging [data-form=upload]')?.scrollIntoView({block:'center',behavior:'smooth'})}else if(im.hasAttribute('data-image-save-notes')){if(!caseId){alert('Önce bir vaka seçin.');return}post('notes',{case_id:caseId,content:imageNotes,body:imageNotes,text:imageNotes}).then(ok=>{if(ok)alert('Not vaka kaydına eklendi.')})}return}const wn=e.target.closest('[data-wizard-nav]');if(wn){const v=wn.dataset.wizardNav;if(v==='back'){caseWizardStep=Math.max(0,caseWizardStep-1);render();return}if(v==='restart'){caseWizardStep=0;caseWizardMode='new';caseWizardDraft=wizardDraftFromCase(null);render();return}if(caseWizardStep===0){if(!caseWizardDraft.patient?.trim()||!caseWizardDraft.subject?.trim()){alert('Hasta kodu ve vaka konusu gerekli.');return}if(caseWizardDraft.age&&(!Number.isInteger(Number(caseWizardDraft.age))||Number(caseWizardDraft.age)<0||Number(caseWizardDraft.age)>125)){alert('Yaş 0–125 arasında olmalı.');return}const payload={...caseWizardDraft};(async()=>{const success=caseWizardMode==='new'?await post('cases',payload):await post('case-update',{...payload,case_id:caseId});if(success){if(caseWizardMode==='new'){caseId=state.cases[0].id;caseWizardMode='edit'}caseWizardStep=1;render()}})();return}caseWizardStep=Math.min(3,caseWizardStep+1);render();return}const wp=e.target.closest('[data-wizard-preview]');if(wp){caseWizardPreview=wp.dataset.wizardPreview;render();return}const at=e.target.closest('[data-assistant-tab]');if(at){assistantTab=at.dataset.assistantTab;render();return}const aq=e.target.closest('[data-quick-prompt]');if(aq){const ta=document.querySelector('.kh-chat-compose textarea');if(ta){ta.value=aq.dataset.quickPrompt;ta.focus()}return}const an=e.target.closest('[data-assistant-new]');if(an){const all=state.messages.filter(m=>m.case_id===caseId);assistantHistoryCutoffs[caseId]=Math.max(0,...all.map(m=>Number(m.id)));assistantTab='chat';render();return}const ah=e.target.closest('[data-assistant-history]');if(ah){assistantHistoryCutoffs[caseId]=0;assistantTab='chat';render();return}const nt=e.target.closest('[data-network-tab]');if(nt){networkTab=nt.dataset.networkTab;networkSelected=null;render();return}const nv=e.target.closest('[data-network-view]');if(nv){networkSelected=Number(nv.dataset.networkView);render();return}const nc=e.target.closest('[data-network-close]');if(nc){networkSelected=null;render();return}const nr=e.target.closest('[data-network-consult]');if(nr){networkSelected=null;stage5Target=nr.dataset.networkConsult;go('consult');stage5Tab='new';render();return}const pr=e.target.closest('[data-patient-request]');if(pr){post('patient-request-status',{id:Number(pr.dataset.patientRequest),status:'inceleniyor'});return}const dest=e.target.closest('[data-page]');if(dest){go(dest.dataset.page);document.getElementById('khMore').hidden=true;document.getElementById('toggleNav').setAttribute('aria-expanded','false');return}const ca=e.target.closest('[data-open-case]');if(ca){caseId=ca.dataset.openCase;go('case');return}const mod=e.target.closest('[data-mode]');if(mod){simMode=mod.dataset.mode;render();return}const sc=e.target.closest('[data-scenario]');if(sc){simScenario=sc.dataset.scenario;render();return}const rp=e.target.closest('[data-report]');if(rp){chosenReport=rp.dataset.report;go('reports');return}const peer=e.target.closest('[data-peer-id]');if(peer){post('peer-consults/respond',{id:Number(peer.dataset.peerId),status:peer.dataset.peerStatus}).then(loadPeers);return}const conn=e.target.closest('[data-connect]');if(conn){post('network/connect',{doctor_id:Number(conn.dataset.connect)}).then(loadNetwork);return}const reply=e.target.closest('[data-connection]');if(reply){post('network/respond',{id:Number(reply.dataset.connection),status:reply.dataset.answer}).then(loadNetwork);return}const ap=e.target.closest('[data-appointment]');if(ap){post('appointment-status',{id:Number(ap.dataset.appointment),status:ap.dataset.status});return}}
function onChange(e){if(e.target.dataset.simLayer){const x=e.target.dataset.simLayer;simLayers=e.target.checked?[...new Set([...simLayers,x])]:simLayers.filter(a=>a!==x);render();return}if(e.target.name==='khSimScenario'){simScenario=e.target.value;render();return}if(e.target.id==='khSimOpacity'){simOpacity=Number(e.target.value);render();return}if(e.target.id==='khImageModality'){imageModality=e.target.value;render();return}if(e.target.id==='imageOpacity'){imageOpacity=Number(e.target.value);render();return}if(e.target.dataset.imageReview){const id=e.target.dataset.imageReview;imageReviewed=e.target.checked?[...new Set([...imageReviewed,id])]:imageReviewed.filter(x=>x!==id);render();return}if(e.target.dataset.wizardLayer){const x=e.target.dataset.wizardLayer;caseWizardLayers=e.target.checked?[...new Set([...caseWizardLayers,x])]:caseWizardLayers.filter(v=>v!==x);return}if(e.target.dataset.wizardField){caseWizardDraft[e.target.dataset.wizardField]=e.target.value;return}if(e.target.id==='wizardCaseMode'){caseWizardMode=e.target.value;caseWizardStep=0;caseWizardDraft=wizardDraftFromCase(caseWizardMode==='edit'?current():null);render();return}if(e.target.id==='wizardExistingCase'){caseId=e.target.value;caseWizardDraft=wizardDraftFromCase(current());caseWizardStep=0;render();return}if(e.target.id==='assistantSourcesToggle'){assistantSources=e.target.checked;return}if(e.target.id==='s5Target'){stage5Target=e.target.value;return}if(e.target.id==='networkSpecialty'){networkSpecialty=e.target.value;render();return}if(e.target.id==='activeCase'){caseId=e.target.value;render()}else if(e.target.dataset.layer){const id=e.target.dataset.layer;imagingLayers=e.target.checked?[...new Set([...imagingLayers,id])]:imagingLayers.filter(l=>l!==id);render()}else if(e.target.id==='reportSelect'){chosenReport=e.target.value;render()}else if(e.target.id==='theme'){theme=e.target.value;localStorage.setItem('kh-theme',theme);render()}else if(e.target.id==='font'){font=e.target.value;localStorage.setItem('kh-font',font);render()}}
async function onSubmit(e){const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const d=Object.fromEntries(new FormData(form));let type=form.dataset.form; if(type==='schedule'){d.days=Array.from({length:7},(_,i)=>i).filter(i=>!!d['day_'+i]);d.duration=Number(d.duration);d.auto_confirm=!!d.auto_confirm;await post('schedule',d)}else if(type==='peerrequest'){if(await post('peer-consults/new',{...d,recipient_id:Number(d.recipient_id)})){stage5Tab='requests';stage5RequestFilter='outgoing';await loadPeers();render()}}else if(type==='peerreply'){if(await post('peer-consults/reply',{...d,id:Number(d.id)}))await loadPeers()}else if(type==='upload'){await uploadFile(form.querySelector('input[type=file]'),caseId)}else if(type==='case'){if(await post('cases',d)){caseId=state.cases[0].id;go('case')}} else if(type==='note')post('notes',{...d,case_id:caseId});else if(type==='message')post('messages',{...d,case_id:caseId});else if(type==='request')post('requests',{...d,case_id:caseId});else if(type==='contact')post('contacts',d);else if(type==='appointment')post('appointments',d);else if(type==='plan')post('plan',{...d,case_id:caseId});else if(type==='userprofile'){d.accepting=!!d.accepting;d.notify=!!d.notify;post('user/profile',d)}else if(type==='password'){const r=await post('user/password',d);if(r)location.href='/'}else if(type==='profile')post('profile',d);else if(type==='report')post('report',{...d,status:'taslak'})}
document.addEventListener('click',onClick);document.addEventListener('change',onChange);document.addEventListener('submit',onSubmit);document.addEventListener('input',e=>{if(e.target.id==='khSimOpacity'){simOpacity=Number(e.target.value);document.querySelector('.kh-sim-range-label span').textContent=simOpacity+'%';return}if(e.target.id==='khImageNotes'){imageNotes=e.target.value;return}if(e.target.id==='imageOpacity'){imageOpacity=Number(e.target.value);document.querySelector('.kh-image-opacity span').textContent=imageOpacity+'%';document.querySelector('.kh-image-scene')?.style.setProperty('opacity',1);return}if(e.target.dataset.wizardField){caseWizardDraft[e.target.dataset.wizardField]=e.target.value;return}if(e.target.id==='networkSearch'){networkSearch=e.target.value;const pos=e.target.selectionStart;render();const n=el('networkSearch');if(n){n.focus();n.setSelectionRange(pos,pos)}}});el('toggleNav').onclick=()=>{const x=el('khMore');x.hidden=!x.hidden;el('toggleNav').setAttribute('aria-expanded',String(!x.hidden))};el('khCloseMore').onclick=()=>{el('khMore').hidden=true;el('toggleNav').setAttribute('aria-expanded','false')};refresh().then(()=>Promise.all([loadNetwork(),loadFiles(),loadPeers()])).catch(err=>{el('content').textContent='Yerel sunucuya erişilemedi: '+err.message});
